    "short_description": {
      "de": "Beta-Carotin ist ein orangefarbener Pflanzenfarbstoff und eine Vorstufe von Vitamin A. Der Körper wandelt nur so viel um, wie er benötigt, weshalb eine Überdosierung über Lebensmittel selten problematisch ist. Gute Quellen sind Karotten, Süßkartoffeln und grünes Blattgemüse.",
      "en": "Beta-carotene is an orange plant pigment and a precursor of vitamin A. The body converts only as much as it needs, so overdosing from food is rarely a problem. Good sources include carrots, sweet potatoes, and leafy greens.",
      "es": "El betacaroteno es un pigmento vegetal anaranjado y un precursor de la vitamina A. El cuerpo solo convierte la cantidad que necesita, por lo que una sobredosis a través de los alimentos rara vez es problemática. Buenas fuentes son zanahorias, batatas y verduras de hoja verde.",
      "it": "Il beta-carotene è un pigmento vegetale arancione e un precursore della vitamina A. L'organismo ne converte solo quanto gli serve, perciò un sovradosaggio alimentare è raramente problematico. Buone fonti sono carote, patate dolci e verdure a foglia verde.",
      "pt": "O betacaroteno é um corante de planta laranja e um precursor da vitamina A. O corpo só converte tanto quanto precisa, e é por isso que a overdose de alimentos raramente é problemática. Boas fontes são cenouras, batatas-doces e vegetais de folhas verdes.",
      "fr": "Le bêta-carotène est un pigment végétal orangé et un précurseur de la vitamine A. L'organisme n'en convertit que la quantité dont il a besoin, si bien qu'un surdosage alimentaire est rarement problématique. De bonnes sources sont les carottes, les patates douces et les légumes verts à feuilles.",
      "tr": "Beta-karoten turuncu bir bitki pigmenti ve A vitamininin öncüsüdür. Vücut yalnızca ihtiyacı kadarını dönüştürür, bu yüzden gıdadan aşırı doz nadiren sorun olur. İyi kaynaklar havuç, tatlı patates ve yeşil yapraklı sebzelerdir."
    },
