    "category": {
      "de": "Stoffwechsel",
      "en": "Metabolism",
      "es": "Metabolismo",
      "it": "Metabolismo",
      "pt": "Metabolismo",
      "fr": "Métabolisme",
      "tr": "Metabolizma"
    },
    "short_description": {
      "de": "Die Beta-Oxidation baut Fettsäuren in den Mitochondrien zu Energie ab. Gute Trainingszustände und ausreichende Mikronährstoffe unterstützen sie. Sehr niedrige Kohlenhydratzufuhr verschiebt den Energiemix stärker Richtung Fett.",
      "en": "Beta-oxidation breaks down fatty acids in mitochondria for energy. Good training status and adequate micronutrients support it. Very low carbohydrate intake shifts the energy mix more toward fat.",
      "es": "La betaoxidación degrada ácidos grasos en las mitocondrias para obtener energía. Buen estado de entrenamiento y micronutrientes suficientes la favorecen. Un aporte muy bajo de hidratos de carbono desplaza más la mezcla energética hacia la grasa.",
      "it": "La beta-ossidazione degrada gli acidi grassi nei mitocondri per energia. Buono stato di allenamento e micronutrienti adeguati la supportano. Un apporto molto basso di carboidrati sposta il mix energetico verso il grasso.",
      "pt": "A beta-oxidação degrada ácidos gordos nas mitocôndrias para energia. Bom estado de treino e micronutrientes adequados apoiam-na. Ingestão muito baixa de hidratos desloca a mistura energética para a gordura.",
      "fr": "La bêta-oxydation dégrade les acides gras dans les mitochondries pour l'énergie. Bon état d'entraînement et micronutriments suffisants la soutiennent. Un apport glucidique très bas décale le mix énergétique vers la graisse.",
      "tr": "Beta-oksidasyon, mitokondride yağ asitlerini enerjiye parçalar. İyi antrenman durumu ve yeterli mikrobesinler destekler. Çok düşük karbonhidrat alımı enerji karışımını yağa kaydırır."
    },
