    "category": {
      "de": "Blutwert",
      "en": "Blood value",
      "es": "Valor sanguíneo",
      "it": "Valore ematico",
      "pt": "Valor sanguíneo",
      "fr": "Valeur sanguine",
      "tr": "Kan değeri"
    },
    "short_description": {
      "de": "Bilirubin entsteht beim Abbau von Hämoglobin und wird von der Leber ausgeschieden. Erhöhte Werte führen zu Ikterus und können auf Leber-, Gallen- oder Hämolyseprobleme hinweisen. Direktes und indirektes Bilirubin differenzieren Ursachen.",
      "en": "Bilirubin forms during hemoglobin breakdown and is excreted by the liver. Elevated values cause jaundice and can point to liver, bile, or hemolysis problems. Direct and indirect bilirubin help differentiate causes.",
      "es": "La bilirrubina se forma en la degradación de la hemoglobina y la elimina el hígado. Valores elevados provocan ictericia y pueden indicar problemas hepáticos, biliares o de hemólisis. La bilirrubina directa e indirecta diferencian causas.",
      "it": "La bilirubina nasce dalla degradazione dell'emoglobina e viene eliminata dal fegato. Valori elevati causano ittero e possono indicare problemi epatici, biliari o emolisi. Bilirubina diretta e indiretta differenziano le cause.",
      "pt": "A bilirrubina forma-se na degradação da hemoglobina e é eliminada pelo fígado. Valores elevados causam icterícia e podem apontar para problemas hepáticos, biliares ou hemolíticos. Bilirrubina direta e indireta diferenciam causas.",
      "fr": "La bilirubine se forme lors de la dégradation de l'hémoglobine et est éliminée par le foie. Des valeurs élevées entraînent un ictère et peuvent indiquer des problèmes hépatiques, biliaires ou d'hémolyse. La bilirubine directe et indirecte différencie les causes.",
      "tr": "Bilirubin hemoglobin yıkımında oluşur ve karaciğer tarafından atılır. Yüksek değerler sarılığa yol açar; karaciğer, safra veya hemoliz sorunlarına işaret edebilir. Direkt ve indirekt bilirubin nedenleri ayırt eder."
    },
