    "short_description": {
      "de": "Blutdruck ist kein klassischer Laborwert aus der Vene, gehört aber eng zu Stoffwechsel und Elektrolyten. Salz, Gewicht und Bewegung beeinflussen ihn stark. Laborwerte wie Kalium und Kreatinin ergänzen die Abklärung.",
      "en": "Blood pressure is not a classic venous lab value but closely relates to metabolism and electrolytes. Salt, weight, and exercise strongly influence it. Lab values like potassium and creatinine complement the workup.",
      "es": "La presión arterial no es un valor clásico de laboratorio venoso, pero está estrechamente ligada al metabolismo y a los electrolitos. Sal, peso y ejercicio la influyen mucho. Valores de laboratorio como potasio y creatinina complementan la evaluación.",
      "it": "La pressione arteriosa non è un classico valore venoso di laboratorio, ma si lega strettamente a metabolismo ed elettroliti. Sale, peso e movimento la influenzano molto. Valori come potassio e creatinina integrano l'accertamento.",
      "pt": "A pressão arterial não é um valor venoso clássico de laboratório, mas liga-se de perto a metabolismo e eletrólitos. Sal, peso e exercício influenciam-na fortemente. Valores como potássio e creatinina complementam a avaliação.",
      "fr": "La tension n'est pas une valeur veineuse classique de labo, mais se lie étroitement au métabolisme et aux électrolytes. Sel, poids et activité l'influencent fortement. Des valeurs comme potassium et créatinine complètent le bilan.",
      "tr": "Kan basıncı klasik venöz lab değeri değildir ama metabolizma ve elektrolitlerle yakından ilişkilidir. Tuz, kilo ve hareket onu güçlü etkiler. Potasyum ve kreatinin gibi lab değerleri değerlendirmeyi tamamlar."
    },
