    "category": {
      "de": "Blutwert",
      "en": "Blood value",
      "es": "Valor sanguíneo",
      "it": "Valore ematico",
      "pt": "Valor sanguíneo",
      "fr": "Valeur sanguine",
      "tr": "Kan değeri"
    },
    "short_description": {
      "de": "Postprandiale Glukose zeigt, wie stark der Blutzucker nach einer Mahlzeit ansteigt. Hohe Spitzen hängen mit glykämischem Index, Portionsgröße und Insulinempfindlichkeit zusammen. CGM-Systeme machen diese Kurven sichtbar.",
      "en": "Postprandial glucose shows how much blood sugar rises after a meal. High peaks relate to glycemic index, portion size, and insulin sensitivity. CGM systems make these curves visible.",
      "es": "La glucosa posprandial muestra cuánto sube la glucemia tras una comida. Los picos altos se relacionan con el índice glucémico, el tamaño de la porción y la sensibilidad a la insulina. Los sistemas CGM hacen visibles estas curvas.",
      "it": "Il glucosio postprandiale mostra quanto sale la glicemia dopo un pasto. Picchi alti si legano a indice glicemico, porzione e sensibilità insulinica. I sistemi CGM rendono visibili queste curve.",
      "pt": "A glicose pós-prandial mostra quão forte sobe a glicemia após uma refeição. Picos altos ligam-se ao índice glicémico, ao tamanho da porção e à sensibilidade à insulina. Sistemas CGM tornam essas curvas visíveis.",
      "fr": "Le glucose postprandial montre combien la glycémie monte après un repas. Des pics élevés se lient à index glycémique, taille de portion et sensibilité à l'insuline. Les CGM rendent ces courbes visibles.",
      "tr": "Postprandiyal glukoz, yemek sonrası kan şekerinin ne kadar yükseldiğini gösterir. Yüksek zirveler glisemik indeks, porsiyon ve insülin duyarlılığıyla ilişkilidir. CGM sistemleri bu eğrileri görünür kılar."
    },
