    "short_description": {
      "de": "C-Peptid entsteht bei der Insulinproduktion und zeigt die eigene Insulinsekretion an. Es hilft, Typ-1- von Typ-2-Mustern und Restfunktion der Bauchspeicheldrüse zu unterscheiden. Exogenes Insulin beeinflusst C-Peptid nicht direkt.",
      "en": "C-peptide is produced during insulin synthesis and indicates endogenous insulin secretion. It helps distinguish type 1 from type 2 patterns and residual pancreatic function. Exogenous insulin does not directly affect C-peptide.",
      "es": "El péptido C se forma en la producción de insulina y muestra la secreción propia de insulina. Ayuda a distinguir patrones de tipo 1 y tipo 2 y la función residual del páncreas. La insulina exógena no influye directamente en el péptido C.",
      "it": "Il peptide C si forma con la produzione di insulina e indica la secrezione insulinica propria. Aiuta a distinguere pattern di tipo 1 e tipo 2 e la funzione residua del pancreas. L'insulina esogena non influenza direttamente il peptide C.",
      "pt": "O peptídeo C forma-se na produção de insulina e mostra a secreção própria de insulina. Ajuda a distinguir padrões de tipo 1 e tipo 2 e a função residual do pâncreas. A insulina exógena não influencia diretamente o peptídeo C.",
      "fr": "Le peptide C se forme lors de la production d'insuline et indique la sécrétion d'insuline propre. Il aide à distinguer les profils de type 1 et de type 2 et la fonction résiduelle du pancréas. L'insuline exogène n'influence pas directement le peptide C.",
      "tr": "C-peptid insülin üretiminde oluşur ve kendi insülin salgısını gösterir. Tip 1 ile tip 2 örüntülerini ve pankreasın kalan işlevini ayırt etmeye yardımcı olur. Dışarıdan verilen insülin C-peptidi doğrudan etkilemez."
    },
