    "short_description": {
      "de": "Calcium ist der wichtigste Baustoff für Knochen und Zähne und spielt eine Rolle bei Muskelkontraktion und Blutgerinnung. Milchprodukte, angereicherte Pflanzenmilch und grünes Gemüse sind typische Quellen. Vitamin D und Bewegung unterstützen die Knochengesundheit maßgeblich.",
      "en": "Calcium is the most important building material for bones and teeth and plays a role in muscle contraction and blood clotting. Dairy products, fortified plant milks, and green vegetables are typical sources. Vitamin D and physical activity substantially support bone health.",
      "es": "El calcio es el principal material de construcción de huesos y dientes y desempeña un papel en la contracción muscular y la coagulación. Lácteos, bebidas vegetales enriquecidas y verduras verdes son fuentes típicas. La vitamina D y el ejercicio apoyan de forma decisiva la salud ósea.",
      "it": "Il calcio è il più importante materiale da costruzione di ossa e denti e interviene nella contrazione muscolare e nella coagulazione. Latticini, bevande vegetali arricchite e verdure verdi sono fonti tipiche. Vitamina D e movimento sostengono in modo decisivo la salute ossea.",
      "pt": "O cálcio é o material de construção mais importante de ossos e dentes e intervém na contração muscular e na coagulação. Laticínios, leites vegetais fortificados e vegetais verdes são fontes típicas. A vitamina D e o exercício apoiam de forma decisiva a saúde óssea.",
      "fr": "Le calcium est le matériau de construction le plus important des os et des dents et intervient dans la contraction musculaire et la coagulation. Produits laitiers, laits végétaux enrichis et légumes verts sont des sources typiques. La vitamine D et l'activité physique soutiennent largement la santé osseuse.",
      "tr": "Kalsiyum kemik ve dişlerin en önemli yapı malzemesidir; kas kasılması ve kan pıhtılaşmasında rol oynar. Süt ürünleri, zenginleştirilmiş bitkisel sütler ve yeşil sebzeler tipik kaynaklardır. D vitamini ve hareket kemik sağlığını önemli ölçüde destekler."
    },
    "related_chapters": [
      7,
      8,
      9
    ]
