    "category": {
      "de": "Blutwert",
      "en": "Blood value",
      "es": "Valor sanguíneo",
      "it": "Valore ematico",
      "pt": "Valor sanguíneo",
      "fr": "Valeur sanguine",
      "tr": "Kan değeri"
    },
    "short_description": {
      "de": "Cortisol folgt einer Tagesrhythmik und beeinflusst Zucker, Blutdruck und Entzündung. Morgenwerte und Funktionstests dienen der Abklärung von Über- oder Unterfunktion. Chronischer Stress ist nicht gleichbedeutend mit krankhaft hohen Werten.",
      "en": "Cortisol follows a daily rhythm and affects sugar, blood pressure, and inflammation. Morning values and function tests help evaluate over- or underactivity. Chronic stress is not the same as pathologically high levels.",
      "es": "El cortisol sigue un ritmo diario e influye en azúcar, presión arterial e inflamación. Valores matutinos y pruebas funcionales sirven para aclarar hiper- o hipofunción. El estrés crónico no equivale a valores patológicamente altos.",
      "it": "Il cortisolo segue un ritmo giornaliero e influenza zucchero, pressione e infiammazione. Valori mattutini e test funzionali servono a chiarire iper o ipofunzione. Lo stress cronico non equivale a valori patologicamente alti.",
      "pt": "O cortisol segue um ritmo diário e influencia açúcar, pressão arterial e inflamação. Valores matinais e testes funcionais servem para esclarecer hiper ou hipofunção. O stresse crónico não equivale a valores patologicamente altos.",
      "fr": "Le cortisol suit un rythme journalier et influence sucre, tension et inflammation. Valeurs du matin et tests fonctionnels servent à clarifier hyper- ou hypofonction. Le stress chronique n'équivaut pas à des taux pathologiquement élevés.",
      "tr": "Kortizol günlük ritmi izler; şeker, kan basıncı ve inflamasyonu etkiler. Sabah değerleri ve işlev testleri aşırı veya yetersiz işlevi aydınlatır. Kronik stres, patolojik yüksek değerlerle aynı değildir."
    },
    "related_chapters": [
      3,
      9
    ]
