    "short_description": {
      "de": "CRP steigt rasch bei bakteriellen Infekten und Gewebeschäden. Es ist ein unspezifischer Entzündungsmarker und sagt allein keine Diagnose. Verlauf und Klinik sind entscheidend.",
      "en": "CRP rises quickly with bacterial infections and tissue injury. It is a nonspecific inflammation marker and alone does not make a diagnosis. Course and clinical findings are decisive.",
      "es": "La PCR sube con rapidez en infecciones bacterianas y daños tisulares. Es un marcador inflamatorio inespecífico y por sí sola no da un diagnóstico. Evolución y clínica son decisivas.",
      "it": "La PCR sale rapidamente in infezioni batteriche e danni tissutali. È un marcatore infiammatorio aspecifico e da sola non pone una diagnosi. Decorso e quadro clinico sono decisivi.",
      "pt": "A PCR sobe rapidamente em infeções bacterianas e lesões tecidulares. É um marcador inespecífico de inflamação e, isolada, não faz diagnóstico. Evolução e clínica são decisivas.",
      "fr": "La CRP augmente rapidement en cas d'infections bactériennes et de lésions tissulaires. C'est un marqueur d'inflammation non spécifique et ne pose pas à elle seule de diagnostic. L'évolution et la clinique sont décisives.",
      "tr": "CRP bakteriyel enfeksiyonlarda ve doku hasarında hızla yükselir. Spesifik olmayan bir enflamasyon belirtecidir; tek başına tanı koymaz. Seyir ve klinik belirleyicidir."
    },
