    "short_description": {
      "de": "De-novo-Lipogenese ist die Neubildung von Fett aus Kohlenhydraten, vor allem in der Leber. Hohe Fruktose- und Kalorienüberschüsse fördern diesen Weg. Erhöhte Triglyceride können ein Hinweis sein.",
      "en": "De novo lipogenesis is the making of new fat from carbohydrates, mainly in the liver. High fructose and calorie surplus favor this pathway. Elevated triglycerides can be a clue.",
      "es": "La lipogénesis de novo es la formación nueva de grasa a partir de hidratos de carbono, sobre todo en el hígado. Excesos altos de fructosa y calorías favorecen esta vía. Triglicéridos elevados pueden ser un indicio.",
      "it": "La lipogenesi de novo è la neoformazione di grasso da carboidrati, soprattutto nel fegato. Elevati eccessi di fruttosio e calorie favoriscono questa via. Trigliceridi alti possono essere un indizio.",
      "pt": "A lipogénese de novo é a formação de gordura nova a partir de hidratos, sobretudo no fígado. Excessos elevados de frutose e calorias favorecem esta via. Triglicéridos elevados podem ser um indício.",
      "fr": "La lipogenèse de novo est la formation de graisse nouvelle à partir de glucides, surtout dans le foie. De forts excès de fructose et de calories favorisent cette voie. Des triglycérides élevés peuvent être un indice.",
      "tr": "De novo lipogenez, özellikle karaciğerde karbonhidratlardan yeni yağ oluşumudur. Yüksek fruktoz ve kalori fazlası bu yolu destekler. Yüksek trigliserit ipucu olabilir."
    },
