      "en": "DHEAS is an adrenal hormone measured in certain hormonal questions. Extreme values can point to adrenal problems. It plays a minor role in everyday nutrition.",
      "es": "El DHEAS es una hormona suprarrenal y se mide en ciertas cuestiones hormonales. Valores extremos pueden apuntar a problemas de las glándulas suprarrenales. Para la alimentación cotidiana desempeña un papel secundario.",
      "it": "Il DHEAS è un ormone surrenalico misurato in certi quesiti ormonali. Valori estremi possono indicare problemi surrenalici. Nell'alimentazione quotidiana ha un ruolo secondario.",
      "pt": "A DHEAS é uma hormona adrenal medida em certas questões hormonais. Valores extremos podem apontar problemas adrenais. Na nutrição do dia a dia tem um papel secundário.",
      "fr": "La DHEAS est une hormone surrénalienne mesurée dans certaines questions hormonales. Des valeurs extrêmes peuvent indiquer des problèmes surrénaliens. Pour l'alimentation quotidienne, son rôle est secondaire.",
      "tr": "DHEAS, belirli hormonal sorularda ölçülen bir adrenal hormondur. Aşırı değerler adrenal sorunlara işaret edebilir. Günlük beslenmede ikincil bir rol oynar."
