    "short_description": {
      "de": "Eisen ist zentral für den Sauerstofftransport im Hämoglobin und für viele Enzyme. Hämeisen aus Fleisch wird besser aufgenommen als Nicht-Hämeisen aus Pflanzen. Vitamin C verbessert, Tee und Kaffee hemmen die Aufnahme aus pflanzlichen Quellen.",
      "en": "Iron is central to oxygen transport in hemoglobin and to many enzymes. Heme iron from meat is absorbed better than non-heme iron from plants. Vitamin C improves, while tea and coffee inhibit absorption from plant sources.",
      "es": "El hierro es central para el transporte de oxígeno en la hemoglobina y para muchas enzimas. El hierro hemo de la carne se absorbe mejor que el no hemo de las plantas. La vitamina C mejora, y el té y el café inhiben, la absorción a partir de fuentes vegetales.",
      "it": "Il ferro è centrale per il trasporto di ossigeno nell'emoglobina e per molti enzimi. Il ferro eme della carne si assorbe meglio del ferro non eme delle piante. La vitamina C migliora, tè e caffè inibiscono l'assorbimento da fonti vegetali.",
      "pt": "O ferro é central para o transporte de oxigénio na hemoglobina e para muitas enzimas. O ferro heme da carne absorve-se melhor do que o não heme das plantas. A vitamina C melhora, chá e café inibem a absorção de fontes vegetais.",
      "fr": "Le fer est central pour le transport de l'oxygène dans l'hémoglobine et pour de nombreuses enzymes. Le fer héminique de la viande s'absorbe mieux que le fer non héminique des plantes. La vitamine C améliore, le thé et le café inhibent l'absorption des sources végétales.",
      "tr": "Demir, hemoglobinde oksijen taşınması ve birçok enzim için merkezidir. Etteki hem demiri bitkisel non-hem demirden daha iyi emilir. C vitamini iyileştirir; çay ve kahve bitkisel kaynaklardan emilimi engeller."
    },
