    "short_description": {
      "de": "Erythrozyten transportieren Sauerstoff und werden im Knochenmark gebildet. Ihre Zahl, Größe und Hämoglobingehalt helfen, Anämieformen zu unterscheiden. Ein Mangel an Eisen, B12 oder Folat verändert typische Muster.",
      "en": "Erythrocytes transport oxygen and are formed in the bone marrow. Their count, size, and hemoglobin content help distinguish anemia types. Iron, B12, or folate deficiency produce typical patterns.",
      "es": "Los eritrocitos transportan oxígeno y se forman en la médula ósea. Su número, tamaño y contenido de hemoglobina ayudan a distinguir formas de anemia. La falta de hierro, B12 o folato modifica patrones típicos.",
      "it": "Gli eritrociti trasportano ossigeno e si formano nel midollo osseo. Numero, volume e contenuto di emoglobina aiutano a distinguere le forme di anemia. Carenze di ferro, B12 o folato modificano i pattern tipici.",
      "pt": "Os eritrócitos transportam oxigénio e formam-se na medula óssea. O seu número, tamanho e teor de hemoglobina ajudam a distinguir formas de anemia. A carência de ferro, B12 ou folato altera padrões típicos.",
      "fr": "Les érythrocytes transportent l'oxygène et sont formés dans la moelle osseuse. Leur nombre, taille et teneur en hémoglobine aident à distinguer les formes d'anémie. Une carence en fer, B12 ou folate modifie des profils typiques.",
      "tr": "Eritrositler oksijen taşır ve kemik iliğinde üretilir. Sayı, boyut ve hemoglobin içeriği anemi tiplerini ayırt etmeye yardımcı olur. Demir, B12 veya folat eksikliği tipik örüntüleri değiştirir."
    },
    "related_chapters": [
      3,
      9
    ]
