    "short_description": {
      "de": "Folsäure ist die synthetische Form von Vitamin B9 und entscheidend für Zellteilung, DNA-Synthese und Blutbildung. Folat bezeichnet die natürlich in Lebensmitteln vorkommenden Formen, etwa in Blattgemüse und Hülsenfrüchten. Ein Mangel kann zu megaloblastärer Anämie und erhöhtem Homocystein führen; in der Schwangerschaft ist eine ausreichende Versorgung besonders wichtig.",
      "en": "Folic acid is the synthetic form of vitamin B9 and is crucial for cell division, DNA synthesis, and blood formation. Folate refers to the forms naturally found in foods such as leafy greens and legumes. Deficiency can lead to megaloblastic anemia and elevated homocysteine; adequate supply is especially important in pregnancy.",
      "es": "El ácido fólico es la forma sintética de la vitamina B9 y es decisivo para la división celular, la síntesis de ADN y la hematopoyesis. Folato designa las formas naturales de los alimentos, por ejemplo en verduras de hoja y legumbres. La deficiencia puede causar anemia megaloblástica y elevación de homocisteína; en el embarazo un aporte adecuado es especialmente importante.",
      "it": "L'acido folico è la forma sintetica della vitamina B9 ed è decisivo per la divisione cellulare, la sintesi del DNA e la formazione del sangue. Folato indica le forme naturali negli alimenti come verdure a foglia e legumi. Una carenza può portare ad anemia megaloblastica e omocisteina elevata; in gravidanza un apporto adeguato è particolarmente importante.",
      "pt": "O ácido fólico é a forma sintética da vitamina B9 e é decisivo para a divisão celular, a síntese de ADN e a formação do sangue. Folato designa as formas naturais nos alimentos, como hortícolas de folha e leguminosas. A deficiência pode levar a anemia megaloblástica e homocisteína elevada; na gravidez um aporte adequado é especialmente importante.",
      "fr": "L'acide folique est la forme synthétique de la vitamine B9 et est crucial pour la division cellulaire, la synthèse de l'ADN et la formation du sang. Folate désigne les formes naturelles des aliments, comme les légumes verts et les légumineuses. Une carence peut entraîner une anémie mégaloblastique et une homocystéine élevée ; pendant la grossesse, un apport suffisant est particulièrement important.",
      "tr": "Folik asit, B9 vitamininin sentetik formudur; hücre bölünmesi, DNA sentezi ve kan oluşumu için kritiktir. Folat, yapraklı sebze ve baklagiller gibi gıdalardaki doğal formları ifade eder. Eksiklik megaloblastik anemiye ve yüksek homosisteine yol açabilir; gebelikte yeterli arz özellikle önemlidir."
    },
