    "short_description": {
      "de": "Freies T3 ist das biologisch aktive Schilddrüsenhormon im Blut. Es wird gemessen, wenn die TSH-Lage unklar ist oder eine Überfunktion vermutet wird. Jod und Selen beeinflussen den Schilddrüsenstoffwechsel.",
      "en": "Free T3 is the biologically active thyroid hormone in blood. It is measured when TSH is unclear or hyperthyroidism is suspected. Iodine and selenium influence thyroid metabolism.",
      "es": "La T3 libre es la hormona tiroidea biológicamente activa en sangre. Se mide cuando el panorama de TSH no está claro o se sospecha hiperfunción. Yodo y selenio influyen en el metabolismo tiroideo.",
      "it": "Il T3 libero è l'ormone tiroideo biologicamente attivo nel sangue. Si misura quando il quadro TSH è poco chiaro o si sospetta un'iperfunzione. Iodio e selenio influenzano il metabolismo tiroideo.",
      "pt": "A T3 livre é a hormona tiroideia biologicamente ativa no sangue. Mede-se quando o quadro da TSH é pouco claro ou se suspeita de hiperfunção. Iodo e selénio influenciam o metabolismo da tiroide.",
      "fr": "La T3 libre est l'hormone thyroïdienne biologiquement active dans le sang. Elle est dosée lorsque le profil TSH est peu clair ou qu'une hyperfonction est suspectée. L'iode et le sélénium influencent le métabolisme thyroïdien.",
      "tr": "Serbest T3, kandaki biyolojik olarak aktif tiroid hormonudur. TSH durumu belirsizse veya hiperfonksiyon şüphesinde ölçülür. İyot ve selenyum tiroid metabolizmasını etkiler."
    },
