    "short_description": {
      "de": "GGT steigt bei Gallenstau, Alkoholbelastung und manchen Medikamenten. Zusammen mit ALP hilft sie, cholestatische Muster zu erkennen. Lebensstiländerungen senken den Wert oft spürbar.",
      "en": "GGT rises with cholestasis, alcohol load, and some medications. Together with ALP it helps recognize cholestatic patterns. Lifestyle changes often lower the value noticeably.",
      "es": "La GGT se eleva en colestasis, carga alcohólica y con algunos medicamentos. Junto con la ALP ayuda a reconocer patrones colestásicos. Los cambios de estilo de vida suelen bajar el valor de forma notable.",
      "it": "La GGT sale in colestasi, carico alcolico e con alcuni farmaci. Insieme all'ALP aiuta a riconoscere pattern colestatici. Cambiamenti dello stile di vita spesso abbassano il valore in modo tangibile.",
      "pt": "A GGT sobe na colestase, na carga alcoólica e com alguns medicamentos. Com a ALP ajuda a reconhecer padrões colestáticos. Mudanças de estilo de vida baixam o valor com frequência de forma notória.",
      "fr": "La GGT augmente en cas de cholestase, de charge alcoolique et de certains médicaments. Avec l'ALP, elle aide à reconnaître des profils cholestatiques. Les changements de mode de vie baissent souvent nettement la valeur.",
      "tr": "GGT safra stazı, alkol yükü ve bazı ilaçlarda yükselir. ALP ile birlikte kolestatik örüntüleri tanımaya yardımcı olur. Yaşam tarzı değişiklikleri değeri çoğu zaman belirgin düşürür."
    },
