    "short_description": {
      "de": "GLP-1 ist ein Darmhormon, das Insulin freisetzt, Magenentleerung verlangsamt und Appetit mindert. Medikamente nutzen diesen Weg therapeutisch. Ballaststoffreiche Mahlzeiten können die natürliche Ausschüttung unterstützen.",
      "en": "GLP-1 is a gut hormone that releases insulin, slows gastric emptying, and reduces appetite. Medications use this pathway therapeutically. Fiber-rich meals can support natural release.",
      "es": "El GLP-1 es una hormona intestinal que libera insulina, ralentiza el vaciamiento gástrico y reduce el apetito. Los medicamentos aprovechan esta vía terapéuticamente. Las comidas ricas en fibra pueden favorecer la liberación natural.",
      "it": "Il GLP-1 è un ormone intestinale che rilascia insulina, rallenta lo svuotamento gastrico e riduce l'appetito. I farmaci usano questa via a scopo terapeutico. Pasti ricchi di fibre possono sostenere il rilascio naturale.",
      "pt": "O GLP-1 é uma hormona intestinal que liberta insulina, abranda o esvaziamento gástrico e reduz o apetite. Medicamentos usam esta via terapeuticamente. Refeições ricas em fibra podem apoiar a libertação natural.",
      "fr": "Le GLP-1 est une hormone intestinale qui libère de l'insuline, ralentit la vidange gastrique et réduit l'appétit. Les médicaments utilisent cette voie thérapeutiquement. Des repas riches en fibres peuvent soutenir la sécrétion naturelle.",
      "tr": "GLP-1, insülin salan, mide boşalmasını yavaşlatan ve iştahı azaltan bir bağırsak hormonudur. İlaçlar bu yolu terapötik kullanır. Lifli öğünler doğal salınımı destekleyebilir."
    },
