    "short_description": {
      "de": "Glukoneogenese erzeugt Glukose aus Aminosäuren und anderen Vorstufen, wenn die Nahrung wenig Kohlenhydrate liefert. Sie hält den Blutzucker für das Gehirn stabil. In Fastenphasen und bei Low-Carb ist sie physiologisch wichtig.",
      "en": "Gluconeogenesis makes glucose from amino acids and other precursors when food provides little carbohydrate. It keeps blood sugar stable for the brain. In fasting and low-carb it is physiologically important.",
      "es": "La gluconeogénesis genera glucosa a partir de aminoácidos y otros precursores cuando la alimentación aporta pocos hidratos de carbono. Mantiene estable la glucemia para el cerebro. En fases de ayuno y en low-carb es fisiológicamente importante.",
      "it": "La gluconeogenesi produce glucosio da aminoacidi e altri precursori quando il cibo fornisce pochi carboidrati. Stabilizza la glicemia per il cervello. Nel digiuno e low-carb è fisiologicamente importante.",
      "pt": "A gluconeogénese produz glicose a partir de aminoácidos e outros precursores quando a comida fornece poucos hidratos. Mantém o açúcar estável para o cérebro. No jejum e low-carb é fisiologicamente importante.",
      "fr": "La néoglucogenèse produit du glucose à partir d'acides aminés et d'autres précurseurs quand l'alimentation fournit peu de glucides. Elle stabilise la glycémie pour le cerveau. En jeûne et low-carb, elle est physiologiquement importante.",
      "tr": "Glukoneogenez, besin az karbonhidrat verdiğinde amino asitler ve diğer öncüllerden glukoz üretir. Beyin için kan şekerini stabil tutar. Oruç ve düşük karbonhidrattta fizyolojik olarak önemlidir."
    },
