    "category": {
      "de": "Stoffwechsel",
      "en": "Metabolism",
      "es": "Metabolismo",
      "it": "Metabolismo",
      "pt": "Metabolismo",
      "fr": "Métabolisme",
      "tr": "Metabolizma"
    },
    "short_description": {
      "de": "Glykogen ist die Speicherform von Glukose in Leber und Muskel. Leberglykogen stabilisiert den Blutzucker, Muskelglykogen treibt die Arbeit. Nach Training und kohlenhydratreichen Mahlzeiten werden die Speicher wieder gefüllt.",
      "en": "Glycogen is the storage form of glucose in liver and muscle. Liver glycogen stabilizes blood sugar; muscle glycogen fuels work. After training and carb-rich meals stores are refilled.",
      "es": "El glucógeno es la forma de almacenamiento de la glucosa en hígado y músculo. El glucógeno hepático estabiliza la glucemia; el muscular impulsa el trabajo. Tras el entrenamiento y comidas ricas en hidratos de carbono se rellenan los depósitos.",
      "it": "Il glicogeno è la forma di deposito del glucosio in fegato e muscolo. Il glicogeno epatico stabilizza la glicemia; quello muscolare alimenta il lavoro. Dopo allenamento e pasti ricchi di carboidrati i depositi si riempiono di nuovo.",
      "pt": "O glicogénio é a forma de armazenamento de glicose no fígado e no músculo. O hepático estabiliza o açúcar; o muscular impulsiona o trabalho. Após treino e refeições ricas em hidratos os depósitos voltam a encher-se.",
      "fr": "Le glycogène est la forme de stockage du glucose dans foie et muscle. Le glycogène hépatique stabilise la glycémie; le musculaire alimente le travail. Après entraînement et repas riches en glucides, les réserves se remplissent.",
      "tr": "Glikojen, karaciğer ve kasta glukozun depo biçimidir. Karaciğer glikojeni kan şekerini dengeler; kas glikojeni işi yürütür. Antrenman ve karbonhidratlı öğünlerden sonra depolar yeniden dolar."
    },
