    "short_description": {
      "de": "Die Glykolyse spaltet Glukose zu Pyruvat und liefert schnell Energie. Bei intensiver Belastung entsteht daraus Laktat. Sie ist der Startpunkt vieler Stoffwechselwege.",
      "en": "Glycolysis splits glucose to pyruvate and supplies energy quickly. Under intense load this yields lactate. It is the starting point of many metabolic pathways.",
      "es": "La glucólisis escinde la glucosa a piruvato y aporta energía con rapidez. Con carga intensa de ahí surge lactato. Es el punto de partida de muchas vías metabólicas.",
      "it": "La glicolisi scinde il glucosio in piruvato e fornisce energia in fretta. Sotto carico intenso ne deriva lattato. È il punto di partenza di molte vie metaboliche.",
      "pt": "A glicólise divide a glicose em piruvato e fornece energia depressa. Sob carga intensa daí surge lactato. É o ponto de partida de muitas vias metabólicas.",
      "fr": "La glycolyse scinde le glucose en pyruvate et fournit de l'énergie rapidement. Sous charge intense, du lactate en résulte. C'est le point de départ de nombreuses voies métaboliques.",
      "tr": "Glikoliz, glukozu pirüvata parçalar ve hızlı enerji sağlar. Yoğun yükte bundan laktat oluşur. Birçok metabolizma yolunun başlangıç noktasıdır."
    },
    "related_chapters": [
      1,
      7
    ]
