    "short_description": {
      "de": "Die glykämische Last verknüpft den glykämischen Index mit der Kohlenhydratmenge pro Portion. Dadurch wird eine kleine Menge eines hochglykämischen Lebensmittels realistischer bewertet. Für den Alltag ist GL oft praxisnäher als GI allein.",
      "en": "Glycemic load links glycemic index to carbohydrate amount per portion. Thus a small amount of a high-GI food is judged more realistically. In daily life GL is often more practical than GI alone.",
      "es": "La carga glucémica vincula el índice glucémico con la cantidad de hidratos de carbono por porción. Así una pequeña cantidad de un alimento de alto IG se valora de forma más realista. En la práctica diaria, la CG suele ser más útil que el IG solo.",
      "it": "Il carico glicemico collega l'indice glicemico alla quantità di carboidrati per porzione. Così una piccola quantità di un alimento ad alto IG si valuta in modo più realistico. Nella vita quotidiana il CG è spesso più pratico dell'IG da solo.",
      "pt": "A carga glicémica liga o índice glicémico à quantidade de hidratos por porção. Assim uma pequena quantidade de um alimento de IG alto avalia-se de forma mais realista. No dia a dia a CG é muitas vezes mais prática do que o IG sozinho.",
      "fr": "La charge glycémique relie l'index glycémique à la quantité de glucides par portion. Ainsi une petite quantité d'un aliment à IG élevé est jugée plus réalistement. Au quotidien, la CG est souvent plus pratique que l'IG seul.",
      "tr": "Glisemik yük, glisemik indeksi porsiyondaki karbonhidrat miktarıyla birleştirir. Böylece yüksek GI'li bir yiyeceğin küçük miktarı daha gerçekçi değerlendirilir. Günlük hayatta GL çoğu zaman yalnızca GI'den daha pratiktir."
    },
