    "category": {
      "de": "Stoffwechsel",
      "en": "Metabolism",
      "es": "Metabolismo",
      "it": "Metabolismo",
      "pt": "Metabolismo",
      "fr": "Métabolisme",
      "tr": "Metabolizma"
    },
    "short_description": {
      "de": "Hepcidin ist das Schlüsselhormon der Eisenregulation und steigt bei Entzündung. Dann bleibt Eisen in den Speichern gefangen, obwohl Ferritin hoch wirken kann. Das erklärt funktionellen Eisenmangel bei chronischer Krankheit.",
      "en": "Hepcidin is the key hormone of iron regulation and rises with inflammation. Iron then stays trapped in stores even though ferritin may look high. That explains functional iron deficiency in chronic disease.",
      "es": "La hepcidina es la hormona clave de la regulación del hierro y se eleva en inflamación. Entonces el hierro queda atrapado en los depósitos aunque la ferritina parezca alta. Eso explica la ferropenia funcional en enfermedad crónica.",
      "it": "L'epcidina è l'ormone chiave della regolazione del ferro e sale nell'infiammazione. Il ferro resta allora imprigionato nei depositi anche se la ferritina può apparire alta. Ciò spiega la carenza funzionale di ferro nella malattia cronica.",
      "pt": "A hepcidina é a hormona chave da regulação do ferro e sobe com a inflamação. O ferro fica então preso nas reservas embora a ferritina possa parecer alta. Isso explica a deficiência funcional de ferro na doença crónica.",
      "fr": "L'hepcidine est l'hormone clé de la régulation du fer et augmente en inflammation. Le fer reste alors piégé dans les réserves même si la ferritine peut paraître élevée. Cela explique la carence fonctionnelle en fer dans la maladie chronique.",
      "tr": "Hepcidin demir düzenlemesinin anahtar hormonudur ve inflamasyonda yükselir. O zaman ferritin yüksek görünse bile demir depolarda tutsak kalır. Bu, kronik hastalıkta fonksiyonel demir eksikliğini açıklar."
    },
    "related_chapters": [
      3,
      9
    ]
