    "synonyms": {
      "de": [
        "verminderte Insulinempfindlichkeit"
      ],
      "en": [
        "reduced insulin sensitivity"
      ],
      "es": [
        "Sensibilidad a la insulina disminuida"
      ],
      "it": [
        "ridotta sensibilità insulinica"
      ],
      "pt": [
        "sensibilidade à insulina reduzida"
      ],
      "fr": [
        "sensibilité à l'insuline réduite"
      ],
      "tr": [
        "azalmış insülin duyarlılığı"
      ]
    },
    "category": {
      "de": "Stoffwechsel",
      "en": "Metabolism",
      "es": "Metabolismo",
      "it": "Metabolismo",
      "pt": "Metabolismo",
      "fr": "Métabolisme",
      "tr": "Metabolizma"
    },
    "short_description": {
      "de": "Bei Insulinresistenz reagieren Zellen weniger empfindlich auf Insulin, wodurch Blutzucker und Insulinspiegel steigen. Bewegung, Schlaf und weniger Zuckerüberschuss verbessern die Empfindlichkeit oft spürbar. HOMA-IR und Taillenumfang sind Orientierungshilfen.",
      "en": "In insulin resistance, cells respond less to insulin, so blood sugar and insulin levels rise. Exercise, sleep, and less excess sugar often improve sensitivity noticeably. HOMA-IR and waist circumference are useful guides.",
      "es": "En la resistencia a la insulina las células reaccionan con menos sensibilidad a la insulina, por lo que suben glucemia e insulina. Ejercicio, sueño y menos exceso de azúcar suelen mejorar la sensibilidad de forma notable. HOMA-IR y perímetro de cintura son ayudas orientativas.",
      "it": "Nell'insulinoresistenza le cellule rispondono meno all'insulina e salgono glicemia e insulina. Movimento, sonno e meno eccesso di zucchero spesso migliorano sensibilmente la sensibilità. HOMA-IR e circonferenza vita orientano.",
      "pt": "Na resistência à insulina, as células respondem menos à insulina e sobem glicemia e insulina. Exercício, sono e menos excesso de açúcar melhoram muitas vezes a sensibilidade. HOMA-IR e perímetro da cintura orientam.",
      "fr": "En résistance à l'insuline, les cellules répondent moins à l'insuline et glycémie et insuline montent. Activité, sommeil et moins d'excès de sucre améliorent souvent nettement la sensibilité. HOMA-IR et tour de taille orientent.",
      "tr": "İnsülin direncinde hücreler insüline daha az yanıt verir; kan şekeri ve insülin yükselir. Hareket, uyku ve daha az şeker fazlası duyarlılığı çoğu zaman belirgin iyileştirir. HOMA-IR ve bel çevresi yönlendiricidir."
    },
