    "category": {
      "de": "Stoffwechsel",
      "en": "Metabolism",
      "es": "Metabolismo",
      "it": "Metabolismo",
      "pt": "Metabolismo",
      "fr": "Métabolisme",
      "tr": "Metabolizma"
    },
    "short_description": {
      "de": "Eine hohe Insulinsensitivität bedeutet, dass wenig Insulin reicht, um Glukose aufzunehmen. Ausdauer- und Krafttraining sind besonders wirksame Hebel. Auch Ballaststoffe und gewichtsneutrale Ernährungsmuster unterstützen sie.",
      "en": "High insulin sensitivity means little insulin is enough to take up glucose. Endurance and strength training are especially effective levers. Fiber and weight-stable eating patterns also support it.",
      "es": "Una alta sensibilidad a la insulina significa que poca insulina basta para absorber glucosa. El entrenamiento de resistencia y de fuerza son palancas especialmente eficaces. También la fibra y patrones alimentarios con peso estable la favorecen.",
      "it": "Un'alta sensibilità insulinica significa che poca insulina basta per captare glucosio. Allenamento di resistenza e di forza sono leve particolarmente efficaci. Fibre e schemi alimentari neutri sul peso la supportano.",
      "pt": "Uma elevada sensibilidade à insulina significa que pouca insulina basta para captar glicose. Treino de resistência e de força são alavancas especialmente eficazes. Fibra e padrões alimentares estáveis no peso também a apoiam.",
      "fr": "Une haute sensibilité à l'insuline signifie que peu d'insuline suffit pour capter le glucose. Endurance et musculation sont des leviers particulièrement efficaces. Fibres et modes alimentaires stables en poids la soutiennent aussi.",
      "tr": "Yüksek insülin duyarlılığı, glukoz alımı için az insülinin yetmesi demektir. Dayanıklılık ve kuvvet antrenmanı özellikle etkili kaldıraçlardır. Lif ve kilo dengeli beslenme kalıpları da destekler."
    },
