    "short_description": {
      "de": "Jod ist essenziell für die Bildung der Schilddrüsenhormone T3 und T4. Jodiertes Speisesalz, Seefisch und Milchprodukte sind wichtige Quellen in Deutschland. Sowohl Mangel als auch deutliche Überschüsse belasten die Schilddrüse.",
      "en": "Iodine is essential for formation of the thyroid hormones T3 and T4. Iodized table salt, sea fish, and dairy products are important sources in Germany. Both deficiency and clear excess strain the thyroid.",
      "es": "El yodo es esencial para la formación de las hormonas tiroideas T3 y T4. La sal yodada, el pescado de mar y los lácteos son fuentes importantes en muchos países. Tanto la deficiencia como los excesos marcados sobrecargan la tiroides.",
      "it": "Lo iodio è essenziale per la formazione degli ormoni tiroidei T3 e T4. Sale da cucina iodato, pesce di mare e latticini sono fonti importanti in Italia e in molti paesi europei. Sia la carenza sia un eccesso marcato gravano sulla tiroide.",
      "pt": "O iodo é essencial para a formação das hormonas da tiroide T3 e T4. Sal de mesa iodado, peixe do mar e laticínios são fontes importantes na Europa Central. Tanto a deficiência como um excesso claro sobrecarregam a tiroide.",
      "fr": "L'iode est essentiel à la formation des hormones thyroïdiennes T3 et T4. Le sel de table iodé, le poisson de mer et les produits laitiers sont des sources importantes en Allemagne. Carence comme excès net sollicitent la thyroïde.",
      "tr": "İyot, tiroit hormonları T3 ve T4 oluşumu için esastır. İyotlu sofra tuzu, deniz balığı ve süt ürünleri Almanya'da önemli kaynaklardır. Hem eksiklik hem belirgin fazlalık tiroidi zorlar."
    },
