    "short_description": {
      "de": "Kalium reguliert Herzrhythmus, Blutdruck und den Flüssigkeitshaushalt in den Zellen. Obst, Gemüse und Hülsenfrüchte liefern reichlich davon. Sehr hohe oder niedrige Blutwerte können gefährlich sein und gehören ärztlich abgeklärt.",
      "en": "Potassium regulates heart rhythm, blood pressure, and fluid balance in the cells. Fruit, vegetables, and legumes supply plenty of it. Very high or low blood values can be dangerous and need medical evaluation.",
      "es": "El potasio regula el ritmo cardíaco, la presión arterial y el equilibrio hídrico celular. Frutas, verduras y legumbres aportan cantidades abundantes. Valores sanguíneos muy altos o muy bajos pueden ser peligrosos y requieren valoración médica.",
      "it": "Il potassio regola il ritmo cardiaco, la pressione arteriosa e l'equilibrio idrico nelle cellule. Frutta, verdura e legumi ne forniscono in abbondanza. Valori ematici molto alti o bassi possono essere pericolosi e vanno valutati dal medico.",
      "pt": "O potássio regula o ritmo cardíaco, a pressão arterial e o equilíbrio hídrico nas células. Fruta, legumes e leguminosas fornecem-no em abundância. Valores sanguíneos muito altos ou baixos podem ser perigosos e devem ser esclarecidos clinicamente.",
      "fr": "Le potassium régule le rythme cardiaque, la tension artérielle et l'équilibre hydrique dans les cellules. Fruits, légumes et légumineuses en apportent largement. Des valeurs sanguines très élevées ou basses peuvent être dangereuses et nécessitent une évaluation médicale.",
      "tr": "Potasyum kalp ritmini, kan basıncını ve hücrelerdeki sıvı dengesini düzenler. Meyve, sebze ve baklagiller bol miktarda sağlar. Çok yüksek veya düşük kan değerleri tehlikeli olabilir ve hekim değerlendirmesi gerekir."
    },
