    "short_description": {
      "de": "Knochenmineralisation beschreibt den Einbau von Calcium und Phosphat in die Knochenmatrix. Sie hängt von Vitamin D, K, Belastung und Hormonen ab. Laborwerte wie Calcium, Phosphat und Vitamin D helfen bei der Einschätzung.",
      "en": "Bone mineralization describes the incorporation of calcium and phosphate into the bone matrix. It depends on vitamins D and K, loading, and hormones. Lab values such as calcium, phosphate, and vitamin D help with assessment.",
      "es": "La mineralización ósea describe la incorporación de calcio y fosfato a la matriz ósea. Depende de las vitaminas D y K, la carga mecánica y las hormonas. Valores de laboratorio como calcio, fosfato y vitamina D ayudan en la valoración.",
      "it": "La mineralizzazione ossea descrive l'incorporazione di calcio e fosfato nella matrice ossea. Dipende dalle vitamine D e K, dal carico e dagli ormoni. Valori di laboratorio come calcio, fosfato e vitamina D aiutano nella valutazione.",
      "pt": "A mineralização óssea descreve a incorporação de cálcio e fosfato na matriz óssea. Depende da vitamina D, da vitamina K, da carga mecânica e das hormonas. Valores laboratoriais como cálcio, fosfato e vitamina D ajudam na avaliação.",
      "fr": "La minéralisation osseuse décrit l'incorporation de calcium et de phosphate dans la matrice osseuse. Elle dépend des vitamines D et K, de la charge et des hormones. Des valeurs biologiques comme calcium, phosphate et vitamine D aident à l'évaluation.",
      "tr": "Kemik mineralizasyonu, kalsiyum ve fosfatın kemik matrisine yerleşmesini tanımlar. D ve K vitaminleri, yüklenme ve hormonlara bağlıdır. Kalsiyum, fosfat ve D vitamini gibi laboratuvar değerleri değerlendirmeye yardımcı olur."
    },
