    "short_description": {
      "de": "Koffein steigert vorübergehend Wachheit und kann die Leistung im Sport leicht verbessern. Empfindliche Personen reagieren mit Herzrasen oder Schlafproblemen. Die Eisenaufnahme aus pflanzlichen Speisen kann durch Kaffee zu den Mahlzeiten sinken.",
      "en": "Caffeine temporarily increases alertness and can slightly improve athletic performance. Sensitive people may react with a racing heart or sleep problems. Coffee with meals can lower iron absorption from plant foods.",
      "es": "La cafeína aumenta temporalmente la alerta y puede mejorar ligeramente el rendimiento deportivo. Las personas sensibles reaccionan con taquicardia o problemas de sueño. La absorción de hierro de comidas vegetales puede bajar con café en las comidas.",
      "it": "La caffeina aumenta temporaneamente la vigilanza e può migliorare leggermente la prestazione sportiva. Le persone sensibili possono reagire con tachicardia o disturbi del sonno. Il caffè ai pasti può ridurre l'assorbimento del ferro vegetale.",
      "pt": "A cafeína aumenta temporariamente o alerta e pode melhorar ligeiramente o desempenho desportivo. Pessoas sensíveis podem reagir com taquicardia ou problemas de sono. Café nas refeições pode reduzir a absorção de ferro vegetal.",
      "fr": "La caféine augmente temporairement la vigilance et peut légèrement améliorer la performance sportive. Les personnes sensibles peuvent réagir par palpitations ou troubles du sommeil. Le café aux repas peut réduire l'absorption du fer végétal.",
      "tr": "Kafein geçici olarak uyanıklığı artırır ve sporda performansı hafif iyileştirebilir. Hassas kişilerde çarpıntı veya uyku sorunları olabilir. Öğünlerde kahve bitkisel demir emilimini düşürebilir."
    },
