    "short_description": {
      "de": "Serumkupfer und Coeruloplasmin helfen bei der Abklärung von Kupferstoffwechselstörungen. Erhöhte Werte treten auch als Akute-Phase-Reaktion auf. Zinküberschuss kann Kupfer sekundär senken.",
      "en": "Serum copper and ceruloplasmin help evaluate copper metabolism disorders. Elevated values also occur as an acute-phase reaction. Excess zinc can secondarily lower copper.",
      "es": "El cobre sérico y la ceruloplasmina ayudan a aclarar trastornos del metabolismo del cobre. Valores elevados también aparecen como reacción de fase aguda. El exceso de zinc puede bajar el cobre de forma secundaria.",
      "it": "Rame sierico e ceruloplasmina aiutano a chiarire disturbi del metabolismo del rame. Valori elevati compaiono anche come reazione di fase acuta. L'eccesso di zinco può abbassare secondariamente il rame.",
      "pt": "O cobre sérico e a ceruloplasmina ajudam a esclarecer perturbações do metabolismo do cobre. Valores elevados também surgem como reação de fase aguda. O excesso de zinco pode baixar secundariamente o cobre.",
      "fr": "Le cuivre sérique et la céruloplasmine aident à préciser les troubles du métabolisme du cuivre. Des valeurs élevées surviennent aussi comme réaction de phase aiguë. Un excès de zinc peut abaisser secondairement le cuivre.",
      "tr": "Serum bakır ve seruloplazmin bakır metabolizması bozukluklarının açıklığa kavuşturulmasına yardım eder. Yüksek değerler akut faz reaksiyonu olarak da görülür. Çinko fazlalığı bakırı ikincil düşürebilir."
    },
