    "category": {
      "de": "Blutwert",
      "en": "Blood value",
      "es": "Valor sanguíneo",
      "it": "Valore ematico",
      "pt": "Valor sanguíneo",
      "fr": "Valeur sanguine",
      "tr": "Kan değeri"
    },
    "short_description": {
      "de": "Lymphozyten steuern die gezielte Immunabwehr und umfassen T- und B-Zellen. Viral bedingte Infekte können sie erhöhen, während Stress oder Cortison sie senken. Das Differenzialblutbild setzt sie in Relation zu anderen Leukozyten.",
      "en": "Lymphocytes drive adaptive immunity and include T and B cells. Viral infections can raise them, while stress or cortisone can lower them. The differential blood count relates them to other leukocytes.",
      "es": "Los linfocitos dirigen la defensa inmunitaria específica e incluyen células T y B. Las infecciones virales pueden elevarlos, mientras que el estrés o la cortisona los bajan. La fórmula leucocitaria los sitúa en relación con otros leucocitos.",
      "it": "I linfociti guidano l'immunità adattativa e includono cellule T e B. Infezioni virali possono aumentarli; stress o cortisone possono ridurli. L'emocromo differenziale li mette in relazione con altri leucociti.",
      "pt": "Os linfócitos dirigem a imunidade adaptativa e incluem células T e B. Infeções virais podem elevá-los; stress ou cortisona podem baixá-los. O hemograma diferencial relaciona-os com outros leucócitos.",
      "fr": "Les lymphocytes pilotent l'immunité adaptative et comprennent les cellules T et B. Les infections virales peuvent les élever; stress ou cortisone peuvent les baisser. La formule leucocytaire les situe par rapport aux autres leucocytes.",
      "tr": "Lenfositler adaptif bağışıklığı yönetir ve T ile B hücrelerini kapsar. Viral enfeksiyonlar yükseltebilir; stres veya kortizon düşürebilir. Diferansiyel kan sayımı onları diğer lökositlerle ilişkilendirir."
    },
    "related_chapters": [
      9
    ]
