    "short_description": {
      "de": "Methylmalonsäure steigt spezifisch bei funktionellem Vitamin-B12-Mangel. Der Wert hilft, Grenzfälle des Serum-B12 zu klären. Niereninsuffizienz kann MMA ebenfalls erhöhen.",
      "en": "Methylmalonic acid rises specifically in functional vitamin B12 deficiency. The value helps clarify borderline serum B12 cases. Kidney failure can also raise MMA.",
      "es": "El ácido metilmalónico se eleva de forma específica en deficiencia funcional de vitamina B12. El valor ayuda a aclarar casos límite de B12 sérica. La insuficiencia renal también puede elevar el MMA.",
      "it": "L'acido metilmalonico sale in modo specifico nella carenza funzionale di vitamina B12. Il valore aiuta a chiarire i casi borderline di B12 sierica. L'insufficienza renale può elevare anch'essa l'MMA.",
      "pt": "O ácido metilmalónico sobe de forma específica na deficiência funcional de vitamina B12. O valor ajuda a esclarecer casos limítrofes de B12 sérica. A insuficiência renal também pode elevar o MMA.",
      "fr": "L'acide méthylmalonique monte de façon spécifique en cas de carence fonctionnelle en vitamine B12. La valeur aide à clarifier les cas limites de B12 sérique. L'insuffisance rénale peut aussi élever le MMA.",
      "tr": "Metilmalonik asit, işlevsel B12 vitamini eksikliğinde özgül olarak yükselir. Değer, sınırda serum B12 olgularını netleştirmeye yardım eder. Böbrek yetmezliği de MMA'yı yükseltebilir."
    },
