    "category": {
      "de": "Mineralstoff",
      "en": "Mineral",
      "es": "Mineral",
      "it": "Minerale",
      "pt": "Mineral",
      "fr": "Minéral",
      "tr": "Mineral"
    },
    "short_description": {
      "de": "Natrium ist der zentrale Elektrolyt außerhalb der Zellen und steuert Blutdruck sowie Wasserhaushalt. Der Großteil der Zufuhr stammt aus verarbeiteten Lebensmitteln und Speisesalz. Eine Reduktion kann bei Bluthochdruck hilfreich sein.",
      "en": "Sodium is the central electrolyte outside the cells and controls blood pressure and water balance. Most intake comes from processed foods and table salt. Reducing intake can help with high blood pressure.",
      "es": "El sodio es el electrolito central fuera de las células y controla la presión arterial y el equilibrio hídrico. La mayor parte del aporte proviene de alimentos procesados y sal de mesa. Reducirlo puede ser útil en hipertensión.",
      "it": "Il sodio è l'elettrolita centrale fuori dalle cellule e controlla pressione arteriosa e bilancio idrico. Gran parte dell'apporto proviene da alimenti processati e sale da cucina. Ridurlo può aiutare nell'ipertensione.",
      "pt": "O sódio é o eletrólito central fora das células e controla a pressão arterial e o equilíbrio hídrico. A maior parte do aporte vem de alimentos processados e sal de mesa. Reduzi-lo pode ajudar na hipertensão.",
      "fr": "Le sodium est l'électrolyte central hors des cellules et contrôle tension artérielle et équilibre hydrique. L'essentiel de l'apport vient des aliments transformés et du sel de table. Le réduire peut aider en cas d'hypertension.",
      "tr": "Sodyum hücre dışı başlıca elektrolittir; kan basıncını ve su dengesini yönetir. Alımın büyük kısmı işlenmiş gıdalar ve sofra tuzundan gelir. Azaltmak yüksek tansiyonda yardımcı olabilir."
    },
