    "short_description": {
      "de": "Natriumchlorid ist das klassische Speisesalz und liefert Natrium sowie Chlorid. Fertigprodukte, Brot und Wurst tragen oft mehr zur Zufuhr bei als die Salzmühle zu Hause. WHO und Fachgesellschaften empfehlen, die Gesamtsalzmenge zu begrenzen.",
      "en": "Sodium chloride is classic table salt and supplies sodium and chloride. Ready meals, bread, and sausages often contribute more to intake than the salt shaker at home. WHO and professional societies recommend limiting total salt.",
      "es": "El cloruro de sodio es la sal de mesa clásica y aporta sodio y cloruro. Productos elaborados, pan y embutidos suelen contribuir más al aporte que el salero de casa. La OMS y las sociedades científicas recomiendan limitar la cantidad total de sal.",
      "it": "Il cloruro di sodio è il classico sale da cucina e fornisce sodio e cloruro. Piatti pronti, pane e salumi spesso contribuiscono all'apporto più del saliera a casa. OMS e società scientifiche raccomandano di limitare la quantità totale di sale.",
      "pt": "O cloreto de sódio é o sal de mesa clássico e fornece sódio e cloreto. Pratos prontos, pão e enchidos contribuem muitas vezes mais para a ingestão do que o saleiro em casa. A OMS e as sociedades científicas recomendam limitar a quantidade total de sal.",
      "fr": "Le chlorure de sodium est le sel de table classique et apporte sodium et chlorure. Plats préparés, pain et charcuterie contribuent souvent davantage à l'apport que la salière à la maison. L'OMS et les sociétés savantes recommandent de limiter la quantité totale de sel.",
      "tr": "Sodyum klorür klasik sofra tuzudur; sodyum ve klorür sağlar. Hazır ürünler, ekmek ve şarküteri çoğu zaman evdeki tuzlukten daha fazla katkı yapar. DSÖ ve uzman dernekler toplam tuz miktarının sınırlanmasını önerir."
    },
