    "short_description": {
      "de": "Natriumfluorid wurde historisch in der Kariesprophylaxe und Osteoporoseforschung eingesetzt. Heute dominiert die lokale Fluoridanwendung über Zahnpasta. Systemische Hochdosen gehören nicht in die Selbstmedikation.",
      "en": "Sodium fluoride was historically used in caries prevention and osteoporosis research. Today local fluoride use via toothpaste dominates. Systemic high doses do not belong in self-medication.",
      "es": "El fluoruro de sodio se usó históricamente en la prevención de caries y en investigación sobre osteoporosis. Hoy domina la aplicación local de fluoruro con pasta dental. Dosis sistémicas altas no corresponden a la automedicación.",
      "it": "Il fluoruro di sodio è stato usato storicamente nella prevenzione della carie e nella ricerca sull'osteoporosi. Oggi prevale l'uso locale di fluoruro tramite dentifricio. Dosi sistemiche elevate non rientrano nell'automedicazione.",
      "pt": "O fluoreto de sódio foi usado historicamente na prevenção da cárie e na investigação da osteoporose. Hoje domina o uso local de fluoreto via pasta dentífrica. Doses sistémicas elevadas não pertencem à automedicação.",
      "fr": "Le fluorure de sodium a historiquement été utilisé en prophylaxie carieuse et recherche sur l'ostéoporose. Aujourd'hui l'usage local de fluorure via le dentifrice domine. Les fortes doses systémiques n'ont pas leur place en automédication.",
      "tr": "Sodyum florür tarihsel olarak çürük önleme ve osteoporoz araştırmasında kullanıldı. Bugün diş macunuyla yerel florür uygulaması baskındır. Sistemik yüksek dozlar kendi kendine ilaçlamaya ait değildir."
    },
