    "short_description": {
      "de": "Portionskontrolle steuert Energie- und Kohlenhydratzufuhr unabhängig vom Lebensmittellabel. Große Teller und Packungsgrößen fördern Überessen. Bewusste Mengen helfen besonders bei energiedichten Produkten.",
      "en": "Portion control manages energy and carbohydrate intake independent of the food label. Large plates and pack sizes promote overeating. Mindful amounts help especially with energy-dense products.",
      "es": "El control de porciones regula el aporte de energía e hidratos de carbono con independencia de la etiqueta del alimento. Platos y envases grandes favorecen el sobreconsumo. Cantidades conscientes ayudan sobre todo en productos densos en energía.",
      "it": "Il controllo delle porzioni regola l'apporto di energia e carboidrati indipendentemente dall'etichetta. Piatti e confezioni grandi favoriscono il sovraconsumo. Quantità consapevoli aiutano soprattutto con prodotti ad alta densità energetica.",
      "pt": "O controlo de porções regula a ingestão de energia e hidratos de carbono independentemente do rótulo. Pratos e embalagens grandes favorecem o excesso. Quantidades conscientes ajudam sobretudo com produtos densos em energia.",
      "fr": "Le contrôle des portions régule l'apport énergétique et glucidique indépendamment de l'étiquette. Grands assiettes et formats favorisent la surconsommation. Des quantités conscientes aident surtout pour les produits denses en énergie.",
      "tr": "Porsiyon kontrolü gıda etiketinden bağımsız enerji ve karbonhidrat alımını yönetir. Büyük tabak ve paketler aşırı yemeyi teşvik eder. Bilinçli miktarlar özellikle enerji yoğun ürünlerde yardımcı olur."
    },
