    "short_description": {
      "de": "Der Quick-Wert beschreibt die Gerinnungsfähigkeit über den extrinsischen Weg und hängt von Vitamin-K-abhängigen Faktoren ab. Niedrige Quick-Werte entsprechen einer höheren INR. Leberstörungen können ihn senken.",
      "en": "The Quick value describes clotting ability via the extrinsic pathway and depends on vitamin K–dependent factors. Low Quick values correspond to a higher INR. Liver disorders can lower it.",
      "es": "El valor de Quick describe la capacidad coagulante por la vía extrínseca y depende de factores vitamina K-dependientes. Valores bajos de Quick corresponden a un INR más alto. Los trastornos hepáticos pueden bajarlo.",
      "it": "Il tempo di protrombina (Quick) descrive la capacità coagulativa della via estrinseca e dipende da fattori vitamina K-dipendenti. Valori Quick bassi corrispondono a un INR più alto. Disturbi epatici possono abbassarlo.",
      "pt": "O tempo de Quick descreve a capacidade de coagulação pela via extrínseca e depende de fatores dependentes da vitamina K. Valores de Quick baixos correspondem a um INR mais alto. Distúrbios hepáticos podem baixá-lo.",
      "fr": "Le taux de Quick décrit la capacité de coagulation via la voie extrinsèque et dépend des facteurs vitamine K-dépendants. Des taux de Quick bas correspondent à un INR plus élevé. Les troubles hépatiques peuvent l'abaisser.",
      "tr": "Quick değeri ekstrensek yolla pıhtılaşma yeteneğini tanımlar ve K vitaminine bağımlı faktörlere bağlıdır. Düşük Quick değerleri daha yüksek INR'ye karşılık gelir. Karaciğer bozuklukları onu düşürebilir."
    },
