    "short_description": {
      "de": "Saccharose besteht je zur Hälfte aus Glukose und Fruktose und ist der klassische Haushaltszucker. Sie steckt offen in Süßigkeiten und versteckt in vielen Fertigprodukten. Weniger freie Zucker zu essen ist ein zentraler LabPlate-Alltagstipp.",
      "en": "Sucrose is half glucose and half fructose and is classic table sugar. It is open in sweets and hidden in many processed foods. Eating fewer free sugars is a core LabPlate everyday tip.",
      "es": "La sacarosa consta a partes iguales de glucosa y fructosa y es el azúcar de mesa clásico. Está de forma abierta en dulces y oculta en muchos productos elaborados. Comer menos azúcares libres es un consejo cotidiano central de LabPlate.",
      "it": "Il saccarosio è metà glucosio e metà fruttosio ed è lo zucchero da tavola classico. È evidente nei dolci e nascosto in molti prodotti pronti. Mangiare meno zuccheri liberi è un consiglio quotidiano centrale di LabPlate.",
      "pt": "A sacarose é metade glicose e metade frutose e é o açúcar de mesa clássico. Está aberta em doces e escondida em muitos produtos processados. Comer menos açúcares livres é uma dica quotidiana central do LabPlate.",
      "fr": "Le saccharose est moitié glucose et moitié fructose et est le sucre de table classique. Il est visible dans les sucreries et caché dans de nombreux produits transformés. Moins de sucres libres est un conseil quotidien central de LabPlate.",
      "tr": "Sakkaroz yarı glukoz yarı fruktozdur ve klasik sofra şekeridir. Tatlılarda açıktır; birçok hazır üründe gizlidir. Daha az serbest şeker yemek LabPlate'in temel günlük önerisidir."
    },
