    "short_description": {
      "de": "Sättigung wird über Hormone wie Ghrelin, GLP-1 und Leptin sowie über Magenfüllung gesteuert. Protein und Ballaststoffe erhöhen oft die Sättigung. Stark verarbeitete Lebensmittel können diese Signale umgehen.",
      "en": "Satiety is driven by hormones such as ghrelin, GLP-1, and leptin plus stomach fill. Protein and fiber often increase satiety. Highly processed foods can bypass these signals.",
      "es": "La saciedad se controla mediante hormonas como grelina, GLP-1 y leptina, y mediante el llenado gástrico. Proteína y fibra suelen aumentar la saciedad. Los alimentos ultraprocesados pueden eludir estas señales.",
      "it": "La sazietà è regolata da ormoni come grelina, GLP-1 e leptina e dal riempimento gastrico. Proteine e fibre spesso aumentano la sazietà. Gli alimenti ultraprocessati possono aggirare questi segnali.",
      "pt": "A saciedade é regulada por hormonas como a grelina, o GLP-1 e a leptina, bem como pelo enchimento gástrico. Proteína e fibra aumentam muitas vezes a saciedade. Alimentos muito processados podem contornar estes sinais.",
      "fr": "La satiété est régulée par des hormones comme ghréline, GLP-1 et leptine ainsi que le remplissage gastrique. Protéines et fibres augmentent souvent la satiété. Les aliments ultra-transformés peuvent contourner ces signaux.",
      "tr": "Tokluk; ghrelin, GLP-1 ve leptin gibi hormonlar ile mide doluluğu üzerinden yönetilir. Protein ve lif çoğu zaman tokluğu artırır. Aşırı işlenmiş gıdalar bu sinyalleri atlatabilir."
    },
