    "short_description": {
      "de": "Industrielle Transfettsäuren entstehen bei teilweiser Härtung von Ölen und erhöhen das Herzrisiko. In der EU sind sie stark begrenzt, können aber noch in manchen Produkten vorkommen. Natürliche Spuren in Milchprodukten sind geringer relevant.",
      "en": "Industrial trans fatty acids form during partial hydrogenation of oils and raise heart risk. In the EU they are tightly limited but may still appear in some products. Natural traces in dairy are less relevant.",
      "es": "Los ácidos grasos trans industriales se forman en la hidrogenación parcial de aceites y elevan el riesgo cardiovascular. En la UE están muy limitados, pero aún pueden aparecer en algunos productos. Las trazas naturales en lácteos son menos relevantes.",
      "it": "Gli acidi grassi trans industriali si formano nella idrogenazione parziale degli oli e aumentano il rischio cardiaco. Nell'UE sono fortemente limitati, ma possono ancora comparire in alcuni prodotti. Le tracce naturali nei latticini sono meno rilevanti.",
      "pt": "Os ácidos gordos trans industriais formam-se na hidrogenação parcial de óleos e elevam o risco cardíaco. Na UE estão fortemente limitados, mas ainda podem surgir em alguns produtos. Traços naturais em laticínios são menos relevantes.",
      "fr": "Les acides gras trans industriels se forment lors de l'hydrogénation partielle des huiles et élèvent le risque cardiaque. Dans l'UE ils sont fortement limités, mais peuvent encore figurer dans certains produits. Les traces naturelles des produits laitiers sont moins pertinentes.",
      "tr": "Endüstriyel trans yağ asitleri yağların kısmi hidrojenasyonuyla oluşur ve kalp riskini artırır. AB'de sıkı sınırlıdır ama bazı ürünlerde hâlâ bulunabilir. Süt ürünlerindeki doğal izler daha az önemlidir."
    },
