    "short_description": {
      "de": "Vitamin A ist wichtig für Sehkraft, Haut und Immunabwehr. Der Körper kann es als Retinol aus tierischen Lebensmitteln oder als Vorstufe Beta-Carotin aus pflanzlichen Quellen aufnehmen. Ein Mangel zeigt sich oft zuerst als Nachtblindheit und trockene Schleimhäute.",
      "en": "Vitamin A is important for vision, skin, and immune defense. The body can take it up as retinol from animal foods or as the precursor beta-carotene from plant sources. Deficiency often first appears as night blindness and dry mucous membranes.",
      "es": "La vitamina A es importante para la visión, la piel y la defensa inmunitaria. El organismo puede absorberla como retinol de alimentos de origen animal o como precursor betacaroteno de fuentes vegetales. La deficiencia suele manifestarse primero como ceguera nocturna y mucosas secas.",
      "it": "La vitamina A è importante per la vista, la pelle e le difese immunitarie. L'organismo può assumerla come retinolo da alimenti animali o come precursore beta-carotene da fonti vegetali. Una carenza si manifesta spesso prima con cecità notturna e mucose secche.",
      "pt": "A vitamina A é importante para a visão, a pele e a defesa imunológica. O organismo pode absorvê-la como retinol de alimentos de origem animal ou como o precursor beta-caroteno de fontes vegetais. A deficiência aparece muitas vezes primeiro como cegueira noturna e mucosas secas.",
      "fr": "La vitamine A est importante pour la vue, la peau et les défenses immunitaires. L'organisme peut l'absorber sous forme de rétinol provenant d'aliments animaux ou de précurseur bêta-carotène d'origine végétale. Une carence se manifeste souvent d'abord par une héméralopie et des muqueuses sèches.",
      "tr": "A vitamini görme, cilt ve bağışıklık savunması için önemlidir. Vücut onu hayvansal gıdalardan retinol olarak veya bitkisel kaynaklardan öncü beta-karoten olarak alabilir. Eksiklik çoğu zaman önce gece körlüğü ve kuru mukozalar olarak ortaya çıkar."
    },
