    "short_description": {
      "de": "Der Vitamin-A-Serumwert wird selten routinemäßig gemessen und spiegelt vor allem schwere Mangel- oder Überdosierungszustände. Die Leber speichert große Mengen Retinol. Klinische Zeichen und Ernährungsanamnese bleiben wichtig.",
      "en": "Serum vitamin A is rarely measured routinely and mainly reflects severe deficiency or overdose. The liver stores large amounts of retinol. Clinical signs and dietary history remain important.",
      "es": "El valor sérico de vitamina A rara vez se mide de forma rutinaria y refleja sobre todo estados graves de deficiencia o sobredosis. El hígado almacena grandes cantidades de retinol. Signos clínicos e historia alimentaria siguen siendo importantes.",
      "it": "La vitamina A sierica si misura raramente di routine e riflette soprattutto carenza grave o sovradosaggio. Il fegato accumula grandi quantità di retinolo. Segni clinici e anamnesi alimentare restano importanti.",
      "pt": "A vitamina A sérica raramente se doseia de rotina e reflecte sobretudo deficiência grave ou sobredosagem. O fígado armazena grandes quantidades de retinol. Sinais clínicos e história alimentar continuam importantes.",
      "fr": "La vitamine A sérique est rarement dosée en routine et reflète surtout une carence sévère ou un surdosage. Le foie stocke de grandes quantités de rétinol. Signes cliniques et anamnèse alimentaire restent importants.",
      "tr": "Serum A vitamini nadiren rutin ölçülür ve başlıca ağır eksiklik veya aşırı doz durumlarını yansıtır. Karaciğer büyük miktarda retinol depolar. Klinik bulgular ve beslenme öyküsü önemli kalır."
    },
