    "short_description": {
      "de": "Vitamin B3 ist essenziell für den Energiestoffwechsel und die DNA-Reparatur. Es kommt in Fleisch, Fisch, Erdnüssen und Vollkorn vor; der Körper kann es auch aus Tryptophan bilden. Sehr hohe Dosen Nicotinsäure können Flush und Leberbelastung verursachen.",
      "en": "Vitamin B3 is essential for energy metabolism and DNA repair. It occurs in meat, fish, peanuts, and whole grains; the body can also make it from tryptophan. Very high doses of nicotinic acid can cause flushing and liver strain.",
      "es": "La vitamina B3 es esencial para el metabolismo energético y la reparación del ADN. Se encuentra en carne, pescado, cacahuetes y cereales integrales; el cuerpo también puede formarla a partir de triptófano. Dosis muy altas de ácido nicotínico pueden causar flush y sobrecarga hepática.",
      "it": "La vitamina B3 è essenziale per il metabolismo energetico e la riparazione del DNA. Si trova in carne, pesce, arachidi e cereali integrali; l'organismo può anche formarla dal triptofano. Dosi molto elevate di acido nicotinico possono causare flush e carico epatico.",
      "pt": "A vitamina B3 é essencial para o metabolismo energético e a reparação do ADN. Ocorre em carne, peixe, amendoins e cereais integrais; o organismo também a pode formar a partir do triptofano. Doses muito elevadas de ácido nicotínico podem causar flush e sobrecarga hepática.",
      "fr": "La vitamine B3 est essentielle au métabolisme énergétique et à la réparation de l'ADN. Elle se trouve dans la viande, le poisson, les arachides et les céréales complètes ; l'organisme peut aussi la former à partir du tryptophane. De très fortes doses d'acide nicotinique peuvent provoquer un flush et une charge hépatique.",
      "tr": "B3 vitamini enerji metabolizması ve DNA onarımı için esastır. Et, balık, yer fıstığı ve tam tahılda bulunur; vücut onu triptofandan da oluşturabilir. Çok yüksek nikotinik asit dozları flush ve karaciğer yüklenmesine yol açabilir."
    },
