    "short_description": {
      "de": "Indirekte Marker wie untercarboxyliertes Osteocalcin können Hinweise auf die Vitamin-K-Versorgung geben. Routinemäßig werden sie selten bestimmt. Grünes Blattgemüse bleibt die wichtigste Quelle für Phyllochinon.",
      "en": "Indirect markers such as undercarboxylated osteocalcin can hint at vitamin K supply. They are rarely measured routinely. Green leafy vegetables remain the main source of phylloquinone.",
      "es": "Marcadores indirectos como la osteocalcina subcarboxilada pueden dar indicios del aporte de vitamina K. Rara vez se determinan de forma rutinaria. Las verduras de hoja verde siguen siendo la fuente principal de filoquinona.",
      "it": "Marcatori indiretti come l'osteocalcina sottocarbossilata possono dare indicazioni sullo stato di vitamina K. Di routine si dosano raramente. Le verdure a foglia verde restano la fonte principale di fillochinone.",
      "pt": "Marcadores indiretos como a osteocalcina subcarboxilada podem dar pistas sobre o aporte de vitamina K. Raramente se doseiam de rotina. Hortícolas de folha verde continuam a principal fonte de filoquinona.",
      "fr": "Des marqueurs indirects comme l'ostéocalcine sous-carboxylée peuvent renseigner sur l'apport en vitamine K. Ils sont rarement dosés en routine. Les légumes verts à feuilles restent la principale source de phylloquinone.",
      "tr": "Yetersiz karboksile osteokalsin gibi dolaylı belirteçler K vitamini durumuna ipucu verebilir. Rutin olarak nadiren ölçülür. Yeşil yapraklı sebzeler fillokinonun başlıca kaynağı olmayı sürdürür."
    },
