    "short_description": {
      "de": "VLDL transportiert vor allem Triglyceride aus der Leber ins Blut. Bei Insulinresistenz und hoher Zuckerzufuhr kann die VLDL-Produktion steigen. Daraus entstehen später LDL-Partikel.",
      "en": "VLDL mainly transports triglycerides from the liver into the blood. In insulin resistance and high sugar intake, VLDL production can rise. LDL particles form from it later.",
      "es": "La VLDL transporta sobre todo triglicéridos del hígado a la sangre. En resistencia a la insulina y alto aporte de azúcar puede aumentar la producción de VLDL. De ahí se forman más tarde partículas LDL.",
      "it": "La VLDL trasporta soprattutto trigliceridi dal fegato al sangue. Nell'insulinoresistenza e con alto apporto di zuccheri la produzione di VLDL può aumentare. Da essa derivano poi particelle LDL.",
      "pt": "A VLDL transporta sobretudo triglicerídeos do fígado para o sangue. Na resistência à insulina e com alto aporte de açúcar, a produção de VLDL pode aumentar. Delas formam-se depois partículas LDL.",
      "fr": "Les VLDL transportent surtout des triglycérides du foie vers le sang. En cas de résistance à l'insuline et d'apport élevé en sucre, la production de VLDL peut augmenter. Des particules LDL en dérivent ensuite.",
      "tr": "VLDL başlıca trigliseridleri karaciğerden kana taşır. İnsülin direnci ve yüksek şeker alımında VLDL üretimi artabilir. Daha sonra LDL partikülleri oluşur."
    },
