      "es": "Los polioles endulzan con menos calorías y a menudo menor efecto sobre la glucemia. En cantidades mayores pueden actuar como laxantes. En las etiquetas aparecen con frecuencia en chicles y productos light.",
      "it": "I polialcoli dolcificano con meno calorie e spesso minore impatto sulla glicemia. In quantità elevate possono avere effetto lassativo. In etichetta compaiono spesso in chewing gum e prodotti light.",
      "pt": "Os álcoois de açúcar adoçam com menos calorias e muitas vezes menor impacto na glicemia. Em doses elevadas podem ter efeito laxante. Nos rótulos aparecem frequentemente em pastilhas elásticas e produtos light.",
