    "short_description": {
      "de": "Der systolische Wert ist die höhere Zahl beim Blutdruckmessen und entsteht, wenn das Herz Blut in die Gefäße pumpt. Er wird in mmHg angegeben und oft als erster Wert genannt (z. B. 120/80). Lebensstilfaktoren wie Salz, Bewegung und Gewicht können ihn beeinflussen – das ist Orientierung, keine Diagnose.",
      "en": "The systolic value is the higher number when measuring blood pressure and occurs when the heart pumps blood into the vessels. It is given in mmHg and is often stated first (e.g. 120/80). Lifestyle factors such as salt, activity, and weight can influence it – this is orientation, not a diagnosis.",
      "es": "El valor sistólico es el número más alto al medir la presión arterial y ocurre cuando el corazón bombea sangre a los vasos. Se da en mmHg y suele indicarse primero (por ej. 120/80). Factores del estilo de vida como la sal, la actividad y el peso pueden influir en él – esto es orientación, no un diagnóstico.",
      "it": "Il valore sistolico è il numero più alto nella misurazione della pressione e si ha quando il cuore pompa sangue nei vasi. Si esprime in mmHg ed è spesso indicato per primo (es. 120/80). Stile di vita come sale, movimento e peso possono influenzarlo – è un orientamento, non una diagnosi.",
      "pt": "O valor sistólico é o número mais alto na medição da pressão arterial e ocorre quando o coração bombeia sangue para os vasos. É dado em mmHg e é frequentemente indicado primeiro (por ex. 120/80). Fatores do estilo de vida como sal, atividade e peso podem influenciá-lo – isto é orientação, não um diagnóstico.",
      "fr": "La valeur systolique est le chiffre le plus élevé lors de la mesure de la tension et apparaît lorsque le cœur pompe le sang dans les vaisseaux. Elle s'exprime en mmHg et est souvent indiquée en premier (par ex. 120/80). Le mode de vie (sel, activité, poids) peut l'influencer – ceci est une orientation, pas un diagnostic.",
      "tr": "Sistolik değer, kan basıncı ölçümünde daha yüksek sayıdır ve kalp kanı damarlara pompaladığında oluşur. mmHg cinsinden verilir ve genelde ilk söylenir (ör. 120/80). Tuz, hareket ve kilo gibi yaşam tarzı faktörleri etkileyebilir – bu yönlendirmedir, tanı değildir."
    },
